package com.android.tools.lint.checks;

import com.android.tools.lint.client.api.UElementHandler;
import com.android.tools.lint.detector.api.Category;
import com.android.tools.lint.detector.api.Detector;
import com.android.tools.lint.detector.api.Implementation;
import com.android.tools.lint.detector.api.Issue;
import com.android.tools.lint.detector.api.JavaContext;
import com.android.tools.lint.detector.api.Scope;
import com.android.tools.lint.detector.api.Severity;
import com.android.tools.lint.detector.api.SourceCodeScanner;
import java.util.Collections;
import java.util.List;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.uast.UClass;
import org.jetbrains.uast.UElement;
import org.jetbrains.uast.UMethod;

public class ViewConstructorDetector extends Detector implements SourceCodeScanner {

    private static final String CLASS_VIEW = "android.view.View";
    private static final String CLASS_CONTEXT = "android.content.Context";
    private static final String CLASS_ATTRIBUTE_SET = "android.util.AttributeSet";

    public static final Issue ISSUE = Issue.create(
            "ViewConstructor",
            "Missing View constructors for XML inflation",
            "Custom views must provide a constructor with one of the signatures used by the "
                    + "layout inflater and layout editor: `View(Context)`, `View(Context, "
                    + "AttributeSet)`, or `View(Context, AttributeSet, int)`. Without such a "
                    + "constructor the view cannot be inflated from XML.",
            Category.CORRECTNESS,
            5,
            Severity.WARNING,
            new Implementation(ViewConstructorDetector.class, Scope.JAVA_FILE_SCOPE)
    );

    @Override
    public List<Class<? extends UElement>> getApplicableUastTypes() {
        return Collections.singletonList(UClass.class);
    }

    @Override
    public UElementHandler createUastHandler(@NotNull JavaContext context) {
        return new UElementHandler() {
            @Override
            public void visitClass(@NotNull UClass node) {
                if (node.isAbstract() || node.isInterface() || node.isEnum()) return;
                if (!context.getEvaluator().extendsClass(node, CLASS_VIEW, false)) return;
                // skip android.view.View itself
                if (CLASS_VIEW.equals(node.getQualifiedName())) return;

                for (UMethod method : node.getMethods()) {
                    if (method.isConstructor() && isValidViewConstructor(method)) {
                        return;
                    }
                }

                context.report(ISSUE, node, context.getNameLocation(node),
                        "Custom view " + node.getName() + " is missing a constructor that can be "
                                + "used for XML inflation; add one of: "
                                + "View(Context), View(Context, AttributeSet), or "
                                + "View(Context, AttributeSet, int)");
            }
        };
    }

    private static boolean isValidViewConstructor(UMethod constructor) {
        List<UParameter> params = constructor.getUastParameters();
        int count = params.size();
        if (count == 0 || count > 3) return false;
        if (!isType(params.get(0).getTypeReference(), CLASS_CONTEXT)) return false;
        if (count == 1) return true;
        if (!isType(params.get(1).getTypeReference(), CLASS_ATTRIBUTE_SET)) return false;
        if (count == 2) return true;
        // third param must be int
        return params.get(2).getType().matchesName("int");
    }

    private static boolean isType(UTypeReferenceExpression ref, String fqName) {
        if (ref == null) return false;
        PsiType type = ref.getType();
        if (type == null) return false;
        return type.equalsToText(fqName);
    }
}

